import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const h=JSON.parse('{"title":"Installazione","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/installazione.md","filePath":"admin-guide/installazione.md"}'),r={name:"admin-guide/installazione.md"};function d(c,e,n,s,l,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="installazione" tabindex="-1">Installazione <a class="header-anchor" href="#installazione" aria-label="Permalink to &quot;Installazione&quot;">​</a></h1><h2 id="componenti" tabindex="-1">Componenti <a class="header-anchor" href="#componenti" aria-label="Permalink to &quot;Componenti&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Componente</th><th>Ruolo</th><th>Note</th></tr></thead><tbody><tr><td><code>clarae-cloud</code></td><td>API REST <code>/api/v1</code>, gRPC/SSE per le notifiche, Web UI incorporata (<code>go:embed</code>), job in background</td><td>Un solo binario, <code>--role=api|worker|all</code></td></tr><tr><td>PostgreSQL</td><td>Metadati, changelog, revisioni, utenti, gruppi, audit</td><td>15 o successivo; migrazioni automatiche all&#39;avvio</td></tr><tr><td>Archivio S3</td><td>Blob content-addressed ed archivi di export</td><td>RustFS, MinIO, AWS S3 o compatibile; 2 bucket</td></tr><tr><td>Keycloak</td><td>Autenticazione OIDC (il servizio è solo resource server)</td><td>Realm <code>clarae</code>, vedi <a href="./keycloak.html">Keycloak</a></td></tr></tbody></table><p>Il traffico ha due ingressi: HTTP(S) per API e Web UI, <strong>HTTP/2 (gRPC)</strong> per lo stream di notifiche (in alternativa il client usa SSE su HTTP). Il database deve supportare <code>LISTEN/NOTIFY</code> senza pooler in modalità transaction.</p><h2 id="kubernetes-con-helm" tabindex="-1">Kubernetes con Helm <a class="header-anchor" href="#kubernetes-con-helm" aria-label="Permalink to &quot;Kubernetes con Helm&quot;">​</a></h2><p>Il chart è in <code>deploy/helm/clarae</code> (<code>values.yaml</code> documenta ogni valore).</p><ol><li><p><strong>Preparare le dipendenze:</strong> database e utente PostgreSQL; due bucket (<code>clarae-blobs</code>, <code>clarae-exports</code>) e una chiave con lettura/scrittura; realm Keycloak importato o configurato (<a href="./keycloak.html">Keycloak</a>).</p></li><li><p><strong>Segreti.</strong> Creare un Secret con <code>DATABASE_URL</code>, <code>S3_ACCESS_KEY</code>, <code>S3_SECRET_KEY</code>, <code>KC_ADMIN_CLIENT_SECRET</code> e indicarlo in <code>secret.existingSecret</code> (consigliato), oppure lasciare che il chart lo crei da <code>secret.values</code> (solo prove). In questo caso <code>values.yaml</code> non fornisce valori: il rendering fallisce se una delle quattro chiavi è vuota o vale un segnaposto (<code>change-me</code>…), e il servizio applica la stessa regola all&#39;avvio (<a href="./configurazione.html#segreti-segnaposto">segreti segnaposto</a>).</p></li><li><p><strong>Valori non segreti</strong> in <code>config:</code> (vedi <a href="./configurazione.html">configurazione</a>): <code>OIDC_ISSUER</code>, <code>S3_ENDPOINT</code>, <code>KC_ADMIN_BASE_URL</code>, <code>WEB_UI_ORIGIN</code>, …</p></li><li><p><strong>Immagine.</strong> <code>image.repository</code> e <code>image.tag</code> (l&#39;immagine si costruisce con <code>docker build -f services/cloud/Dockerfile -t &lt;repo&gt;:&lt;tag&gt; .</code> dalla radice del repository; il registry definitivo è da decidere con la distribuzione, M7).</p></li><li><p><strong>Ingress:</strong> <code>ingress.host</code> per HTTP e <code>ingress.grpcHost</code> per gRPC (HTTP/2 end to end, TLS). Con ingress NGINX aggiungere l&#39;annotation <code>nginx.ingress.kubernetes.io/backend-protocol: &quot;GRPC&quot;</code> sull&#39;host gRPC.</p></li><li><p><strong>Installare:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clarae</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/helm/clarae</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clarae</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --create-namespace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span></span></code></pre></div></li></ol><p>Il chart avvia <code>api.replicas</code> repliche con <code>--role=api</code> e <code>worker.replicas</code> (1) con <code>--role=worker</code>. Le probe dell&#39;API usano <code>/api/v1/healthz</code> (liveness) e <code>/api/v1/readyz</code> (readiness); quelle del worker <code>/healthz</code> e <code>/readyz</code> sulla porta interna <code>metrics</code> (<code>worker.metricsPort</code>, 18083). La directory <code>/tmp</code> di ogni pod è un <code>emptyDir</code> limitato (<code>api.tmp.sizeLimit</code> 2Gi per gli upload dei blob, <code>worker.tmp.sizeLimit</code> 10Gi per gli archivi di export; oltre il limite il kubelet sfratta il pod) con richieste e limiti di <code>ephemeral-storage</code> corrispondenti in <code>resources</code>: dimensionarli sugli upload concorrenti e sul vault più grande. Il pod gira come utente non root con profilo seccomp <code>RuntimeDefault</code>.</p><p><strong>Versione di Kubernetes.</strong> Il chart richiede Kubernetes 1.27 o successivo. Il ritardo prima di SIGTERM (<code>api.preStopSleepSeconds</code>, azione <code>preStop</code> di tipo <code>sleep</code>) è reso solo da Kubernetes 1.30, dove l&#39;azione è attiva di default: l&#39;immagine distroless non ha una shell per un <code>exec</code> equivalente. Su 1.27–1.29 l&#39;attesa la fa il processo stesso con <code>SHUTDOWN_DRAIN</code> (default <code>5s</code>: <code>/readyz</code> risponde non pronto mentre il servizio continua a servire), purché <code>api.preStopSleepSeconds</code> + <code>SHUTDOWN_DRAIN</code> + <code>SHUTDOWN_TIMEOUT</code> resti sotto <code>api.terminationGracePeriodSeconds</code>. <code>task helm-check</code> verifica il chart su 1.27 e 1.30.</p><p><strong>Avvio.</strong> Il pod API apre subito la porta HTTP, prima delle migrazioni e della discovery di Keycloak: <code>/api/v1/healthz</code> risponde 200 e <code>/api/v1/readyz</code> 503 finché l&#39;avvio non è completo, e le altre richieste ricevono 503 con <code>Retry-After</code>. Così un&#39;attesa del lock delle migrazioni (fino a 10 minuti) o di Keycloak non fa riavviare il pod; <code>progressDeadlineSeconds</code> è 900 per API e worker.</p><h2 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to &quot;Docker Compose&quot;">​</a></h2><p>Uno stack di <strong>sviluppo</strong> (PostgreSQL, RustFS, Keycloak) è in <code>deploy/docker/compose.dev.yaml</code> (<code>task stack-up</code>) e <strong>non</strong> è pensato per la produzione. Un compose di produzione per installazioni piccole, con proxy TLS (Caddy) e HTTP/2 per gRPC, è in <code>deploy/compose</code> (vedi il suo <code>README.md</code>).</p><h2 id="primo-avvio-e-verifica" tabindex="-1">Primo avvio e verifica <a class="header-anchor" href="#primo-avvio-e-verifica" aria-label="Permalink to &quot;Primo avvio e verifica&quot;">​</a></h2><ol><li>I pod diventano <code>Ready</code>; <code>GET https://&lt;host&gt;/api/v1/readyz</code> risponde <code>{&quot;status&quot;:&quot;ok&quot;}</code>. Tramite l&#39;ingress la risposta non riporta il dettaglio per dipendenza: per vederlo, interrogare il pod direttamente (<code>kubectl port-forward deploy/clarae-api 18081</code> e <code>curl http://127.0.0.1:18081/api/v1/readyz</code>: <code>database</code> e <code>storage</code> a <code>ok</code>).</li><li><code>GET /api/v1/client-config</code> restituisce issuer e client id: è ciò che i client usano per configurarsi partendo dal solo URL del server.</li><li>Accedere alla Web UI con un utente con il ruolo <code>clarae-admin</code>: compare la voce <strong>Amministrazione</strong>.</li><li>Impostare i limiti in <strong>Amministrazione → Limiti</strong> (quota predefinita, conservazione dello storico, dimensione massima file).</li><li>Nell&#39;app desktop: <em>Impostazioni → Cloud</em>, inserire l&#39;URL del server e accedere.</li></ol><h2 id="dimensionamento-indicativo" tabindex="-1">Dimensionamento indicativo <a class="header-anchor" href="#dimensionamento-indicativo" aria-label="Permalink to &quot;Dimensionamento indicativo&quot;">​</a></h2><p>L&#39;API è stateless: si scala con le repliche (2+ consigliate). Un solo worker è sufficiente (i job usano advisory lock, quindi più worker sono sicuri ma ridondanti). Il collo di bottiglia tipico è il database: monitorare il pool (<a href="./monitoraggio.html">monitoraggio</a>). I numeri misurati (indicizzazione, ricerca, carico del cloud) sono in <code>docs/perf/README.md</code>.</p>',16)])])}const m=o(r,[["render",d]]);export{h as __pageData,m as default};
